    "id": "scraped-e1805a7f6335",
    "company": "Population Services International (PSI)",
    "source": "EthioJobs",
    "title": "Coordinator, Grants, Contract and Compliance",
    "location": "Addis Ababa",
    "mode": "Onsite",
    "type": "Full-time Entry Level",
    "experience": "0-2 Years",
    "industry": "Tech",
